#!/system/bin/sh
# init_env.sh — Stronghold 3 Android Wrapper (auto-generated by Bolt Wrapper Builder)
# Extracts minimal Linux rootfs + configures Box86/Box64, Wine (win32), DXVK 1.10.3
# Target: Vision Engine x86 32-bit, DirectX 9.0c -> Vulkan via DXVK

set -e

APP_ROOT="${APP_ROOT:-/data/data/com.bolt.stronghold3wrapper}"
ROOTFS_TAR="${APP_ROOT}/../files/rootfs.tar.xz"
ROOTFS_DIR="${APP_ROOT}/rootfs"
WINEPREFIX="${ROOTFS_DIR}/wineprefix"
MARKER="${ROOTFS_DIR}/.extracted"

log() { echo "[init_env] $*"; }

if [ -f "${MARKER}" ]; then
  log "Rootfs already extracted, skipping."
else
  log "Extracting rootfs from ${ROOTFS_TAR} (first launch only, this takes a while)…"
  mkdir -p "${ROOTFS_DIR}"
  tar -xJf "${ROOTFS_TAR}" -C "${ROOTFS_DIR}"
  touch "${MARKER}"
  log "Rootfs extracted."
fi

log "Creating Wine 32-bit prefix if missing…"
if [ ! -d "${WINEPREFIX}" ]; then
  WINEARCH=win32 WINEPREFIX="${WINEPREFIX}" wineboot -u
  log "Wine prefix created at ${WINEPREFIX}"
fi

log "Installing DXVK 1.10.3 into prefix…"
cp "${ROOTFS_DIR}/dxvk-1.10.3/x32/d3d9.dll" "${WINEPREFIX}/drive_c/windows/system32/"
cp "${ROOTFS_DIR}/dxvk-1.10.3/x32/dxvk.conf" "${WINEPREFIX}/drive_c/windows/system32/"

log "Applying environment overrides…"
export BOX86_DYNAREC="1"
export BOX64_DYNAREC="1"
export DXVK_HUD="fps"
export DXVK_ASYNC="1"
export WINEARCH="win32"
export WINEDLLOVERRIDES="d3d9=n,b;d3dx9_43=n,b;vcruntime140=n,b"
export WINEPREFIX="$ROOTFS/wineprefix"
export BOX86_DYNAREC_FASTNAN="1"
export BOX64_DYNAREC_SAFEFLAGS="2"
export DXVK_STATE_CACHE_PATH="$ROOTFS/cache/xclipse"

log "Done. Rootfs, Wine prefix and DXVK are ready."
